const AdmZip = require('adm-zip');
const PDFDocument = require('pdfkit');
const fs = require('fs');

// Extract text from docx
const zip = new AdmZip('testbed/docs/customer_report.docx');
const entry = zip.getEntry('word/document.xml');
const xml = entry.getData().toString('utf8');

// Parse paragraphs from the XML
const paragraphs = [];
const pRegex = /<w:p[ >].*?<\/w:p>/gs;
let match;
while ((match = pRegex.exec(xml)) !== null) {
  const pXml = match[0];
  // Extract text runs
  const texts = [];
  const tRegex = /<w:t[^>]*>(.*?)<\/w:t>/gs;
  let tMatch;
  while ((tMatch = tRegex.exec(pXml)) !== null) {
    texts.push(tMatch[1]);
  }
  // Check for bold
  const isBold = /<w:b[ />]/.test(pXml) || /<w:b\/>/.test(pXml);
  const text = texts.join('');
  if (text) {
    paragraphs.push({ text, isBold });
  }
}

// Create PDF
const doc = new PDFDocument({ margin: 50, size: 'A4' });
const output = fs.createWriteStream('testbed/docs/customer_report.pdf');
doc.pipe(output);

for (const p of paragraphs) {
  if (p.text === 'Customer Activity Report') {
    doc.fontSize(20).font('Helvetica-Bold').text(p.text, { align: 'center' });
    doc.moveDown(0.8);
  } else if (p.text.startsWith('Email:')) {
    doc.fontSize(10).font('Helvetica').text(p.text);
    doc.moveDown(0.3);
  } else if (p.text.match(/^(Maya|Jordan|Evan|Nina|Alicia|Sofia)/)) {
    doc.moveDown(0.5);
    doc.fontSize(14).font('Helvetica-Bold').text(p.text);
    doc.moveDown(0.2);
  } else if (p.text.startsWith('Order ')) {
    const cancelled = p.text.includes('cancelled');
    doc.fontSize(10).font('Helvetica-Bold').text(p.text.split('—')[0].trim(), { continued: true });
    doc.font('Helvetica').text(' — ' + (p.text.split('—')[1] || ''));
    doc.moveDown(0.15);
  } else if (p.text.startsWith('Items:')) {
    doc.fontSize(9).font('Helvetica').text('    ' + p.text, { color: '#555555' });
    doc.moveDown(0.3);
  } else {
    doc.fontSize(10).font(p.isBold ? 'Helvetica-Bold' : 'Helvetica').text(p.text);
    doc.moveDown(0.3);
  }
}

doc.end();
output.on('finish', () => {
  const stats = fs.statSync('testbed/docs/customer_report.pdf');
  console.log('PDF created successfully: testbed/docs/customer_report.pdf');
  console.log('File size: ' + (stats.size / 1024).toFixed(1) + ' KB');
});
"

