const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('testbed/docs/customer_report.pdf');
const text = buf.toString('binary');

// Find and decompress all streams
const regex = /stream\r?\n([\s\S]*?)endstream/g;
let m;
let allText = '';
while ((m = regex.exec(text)) !== null) {
  try {
    const raw = Buffer.from(m[1], 'binary');
    const inflated = zlib.inflateSync(raw).toString('utf8');
    // Extract text between parentheses (PDF text objects)
    const tMatches = inflated.match(/\(([^)]*)\)/g);
    if (tMatches) {
      allText += tMatches.map(t => t.slice(1,-1)).join('') + '\n';
    }
  } catch(e) {}
}
console.log('PDF text content:');
console.log(allText);
"

